      &lt;se:FeatureTypeStyle&gt;
        &lt;se:Rule&gt;
          &lt;se:Name&gt;Single symbol&lt;/se:Name&gt;
          &lt;se:PolygonSymbolizer&gt;
            &lt;se:Fill&gt;
