              &lt;se:SvgParameter name="stroke-linejoin"&gt;bevel&lt;/se:SvgParameter&gt;
            &lt;/se:Stroke&gt;
          &lt;/se:PolygonSymbolizer&gt;
        &lt;/se:Rule&gt;
      &lt;/se:FeatureTypeStyle&gt;
    &lt;/UserStyle&gt;
  &lt;/NamedLayer&gt;
&lt;/StyledLayerDescriptor&gt;









